// Order placement. Already correct: it validates the promo code first and counts
// the use only after the order succeeds. You do not edit this file.

const PromoCode = require("../models/promoCodeModel");
const { validatePromoCode } = require("./promoCodeService");

const TICKET_PRICE = 500;
const orders = [];

function createOrder(userId, eventId, quantity, promoCodeText) {
  let discountPercent = 0;
  let promo = null;

  if (promoCodeText) {
    promo = validatePromoCode(promoCodeText, eventId, quantity).promo;
    discountPercent = promo.discountPercent;
  }

  const subtotal = TICKET_PRICE * quantity;
  const total = subtotal - (subtotal * discountPercent) / 100;
  const order = { id: orders.length + 1, userId, eventId, quantity, promoCode: promo ? promo.code : null, subtotal, total };
  orders.push(order);

  if (promo) PromoCode.incrementUses(promo.id);
  return order;
}

module.exports = { createOrder };
